#include <SPI.h>
#include <Adafruit_GFX.h>

#define SWRESET 0x01
#define RDID    0x04
#define SLPOUT  0x11
#define INVOFF  0x20
#define INVON   0x21
#define DISPON  0x29
#define CASET   0x2A
#define PASET   0x2B
#define MADCTL  0x36
#define COLMOD  0x3A

class ILI934x : public Adafruit_GFX {
public:
  int8_t _sclk, _mosi, _miso, _cs, _dc, _rst;
  bool _inverted;
  ILI934x(int8_t s, int8_t mosi, int8_t miso, int8_t cs, int8_t dc, int8_t rst, bool inv)
    : Adafruit_GFX(320, 240) {
    _sclk = s; _mosi = mosi; _miso = miso; _cs = cs; _dc = dc; _rst = rst; _inverted = inv;
  }

  void init(uint8_t bl) {
    pinMode(_sclk, OUTPUT); pinMode(_mosi, OUTPUT); pinMode(_cs, OUTPUT); pinMode(_dc, OUTPUT);
    if (_rst >= 0) pinMode(_rst, OUTPUT);
    if (_miso >= 0) pinMode(_miso, INPUT);
    if (bl != 255) { pinMode(bl, OUTPUT); digitalWrite(bl, HIGH); }
    digitalWrite(_sclk, LOW); digitalWrite(_cs, HIGH);
  }

  void w(uint8_t b) {
    for (int i = 7; i >= 0; i--) { digitalWrite(_sclk, LOW); digitalWrite(_mosi, (b >> i) & 1); digitalWrite(_sclk, HIGH); }
    digitalWrite(_sclk, LOW);
  }
  uint8_t r(void) {
    uint8_t v = 0; digitalWrite(_mosi, HIGH);
    for (int i = 0; i < 8; i++) { digitalWrite(_sclk, LOW); digitalWrite(_sclk, HIGH); v = (v << 1) | (digitalRead(_miso) ? 1 : 0); }
    digitalWrite(_sclk, LOW); return v;
  }

  void cmd(uint8_t c) { digitalWrite(_cs, LOW); digitalWrite(_dc, LOW); w(c); digitalWrite(_cs, HIGH); }
  void dat(uint8_t d) { digitalWrite(_cs, LOW); digitalWrite(_dc, HIGH); w(d); digitalWrite(_cs, HIGH); }
  uint32_t rdID(void) {
    digitalWrite(_cs, LOW); digitalWrite(_dc, LOW); w(RDID);
    digitalWrite(_dc, HIGH);
    uint32_t id = 0; for (int i = 0; i < 3; i++) { id = (id << 8) | r(); }
    digitalWrite(_cs, HIGH); return id;
  }

  void begin(uint8_t bl) {
    init(bl);
    if (_rst >= 0) { digitalWrite(_rst, HIGH); delay(5); digitalWrite(_rst, LOW); delay(30); digitalWrite(_rst, HIGH); delay(150); }
    else { cmd(SWRESET); delay(150); }
    cmd(SLPOUT); delay(100);
    cmd(COLMOD); dat(0x55);
    cmd(_inverted ? INVON : INVOFF);
    cmd(DISPON); delay(20);
    setRotation(0);
  }

  void setRotation(uint8_t rot) {
    Adafruit_GFX::setRotation(rot);
    uint8_t mad = 0;
    switch (rot) {
      case 1: mad = 0x80; break;
      case 2: mad = 0xE0; break;
      case 3: mad = 0x40; break;
    }
    cmd(MADCTL); dat(mad);
  }
  void setWin(int16_t x0, int16_t y0, int16_t x1, int16_t y1) {
    cmd(CASET); dat(x0 >> 8); dat(x0); dat(x1 >> 8); dat(x1);
    cmd(PASET); dat(y0 >> 8); dat(y0); dat(y1 >> 8); dat(y1);
  }
  void drawPixel(int16_t x, int16_t y, uint16_t c) {
    if (x < 0 || y < 0 || x >= _width || y >= _height) return;
    digitalWrite(_cs, LOW); setWin(x, y, x, y);
    digitalWrite(_dc, HIGH); w(c >> 8); w(c & 0xFF);
    digitalWrite(_cs, HIGH);
  }
  void fillScreen(uint16_t c) {
    digitalWrite(_cs, LOW); setWin(0, 0, width() - 1, height() - 1);
    digitalWrite(_dc, HIGH);
    for (uint32_t i = 0; i < (uint32_t)width() * height(); i++) { w(c >> 8); w(c & 0xFF); }
    digitalWrite(_cs, HIGH);
  }
};

struct P { int8_t s, mo, miso, cs, dc, rst; uint8_t bl; bool inv; };
const P presets[] = {
  { 18, 23, 19,  5,  2,  4, 27, false },
  { 18, 23, 19,  5,  2,  4, 27, true  },
  { 18, 23, -1,  5,  2,  4, 27, false },
  { 14, 13, 12, 15, 33, 32, 21, false },
  { 18, 23, 19,  5, 21, 22, 27, false },
  { 18, 23, 19, 14, 27, 26, 255, false },
};
const int NUM = sizeof(presets) / sizeof(presets[0]);

void setup() {
  Serial.begin(115200);
  delay(700);
  Serial.println("\n=== Scout start ===");
  for (int i = 0; i < NUM; i++) {
    const P& p = presets[i];
    Serial.printf("Try #%d: SCLK=%d MOSI=%d MISO=%d CS=%d DC=%d RST=%d BL=%d\n",
      i, p.s, p.mo, p.miso, p.cs, p.dc, p.rst, p.bl == 255 ? -1 : p.bl);
    ILI934x tft(p.s, p.mo, p.miso, p.cs, p.dc, p.rst, p.inv);
    tft.begin(p.bl);
    uint32_t id = tft.rdID();
    Serial.printf("   readID=0x%06X\n", id);
    tft.fillScreen(0xFFFF);
    delay(1200);
    int lo = id & 0xFF;
    if ((lo == 0x93 || lo == 0x94) && id != 0) {
      Serial.printf(">>> MATCH preset #%d  ID=0x%06X\n", i, id);
    }
  }
  Serial.println("Done. Смотри Serial: какое readID и на каком шаге мигнул белый.");
}
void loop() { delay(5000); }
